-- ============================================================================
-- mod-gear-ascension -- Phase 1 tier copies (vendor-sold Classic Q2+Q3 set)
-- AUTO-GENERATED by modules/mod-gear-ascension/scripts/gear-ascension-gen-sql.ps1
-- Do not hand-edit. Re-run the generator to regenerate.
--
-- Scope: vendor-sold Classic-only (RequiredLevel<=60, entry<24000)
--   Q2 (green) bases: 64  (2 copies each)
--   Q3 (blue) bases : 251  (1 copy each)
--   Total bases     : 315
--   Total copies    : 379
-- ID map: new_entry = 300000 + baseIndex*10 + step (step 1..3)
--   Proto baseIndex range: 0..314
--   Entry range: [300001..303142]
-- Naming: combined PREFIX+SUFFIX, line=baseIndex mod 6 (0-2=suffix, 3-5=prefix).
--   enUS: prefix "<pre> <name>" or suffix "<name> <suf>"
--   ruRU: same with full gender/number declension (see DESIGN.md sec 10).
--   ruRU ONLY emitted when base has a real ruRU locale row.
--   enUS-only bases: 0
-- PTR ONLY (acore_world_ptr). Idempotent.
-- ============================================================================

-- item_upgrade_chain DDL (idempotent).
CREATE TABLE IF NOT EXISTS item_upgrade_chain (
    entry           INT UNSIGNED NOT NULL COMMENT 'current entry being upgraded FROM (PK)',
    origin_entry    INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'base entry of the line',
    from_quality    TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Quality of entry',
    to_quality      TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Quality of next tier',
    step            TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'tiers above the original; bonus driver',
    next_entry      INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'entry of next tier (success target); 0=ceiling',
    prev_entry      INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'entry of previous tier (downgrade); 0=base',
    bonus_pct       SMALLINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'bonus of next_entry (= 10 * step)',
    kit_profession  VARCHAR(16) NOT NULL DEFAULT '' COMMENT 'blacksmith/leather/tailor/jewel',
    kit_tier        TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'kit tier = to_quality',
    nemesis_rank    INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'min Nemesis rank by to_quality',
    success_pct     TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'success chance 95/75/50',
    gold_cost       INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'optional gold cost (copper)',
    fail_downgrade  TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '1 only when to_quality=4',
    PRIMARY KEY (entry)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Gear Ascension upgrade edges';

-- Idempotency: clear EVERYTHING gear-ascension owns.
-- item_upgrade_chain is exclusively gear-ascension data, so TRUNCATE the whole
-- table (also clears old prototype base-entry rows with entry < 300001).
-- Then clear the full tier-copy ID range for item_template and locale.
TRUNCATE TABLE item_upgrade_chain;
DELETE FROM item_template_locale WHERE ID BETWEEN 300001 AND 306933;
DELETE FROM item_template WHERE entry BETWEEN 300001 AND 306933;

